import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l2_p96_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor fused_maxpool_globalavgpool_clamp_cuda(torch::Tensor x, double clamp_min, double clamp_max, int64_t pool_k);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("fused_maxpool_globalavgpool_clamp_cuda", &fused_maxpool_globalavgpool_clamp_cuda, "Fused maxpool+globalavgpool+clamp (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cfloat>

__global__ void fused_maxpool_globalavgpool_clamp_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    int64_t N, int64_t C, int64_t D, int64_t H, int64_t W,
    int64_t pool_k,
    int64_t Dp, int64_t Hp, int64_t Wp,
    float clamp_min, float clamp_max
) {
    int nc = blockIdx.x;
    int n = nc / C;
    int c = nc % C;

    if (n >= N || c >= C) return;

    int tid = threadIdx.x;
    int block_size = blockDim.x;

    const float* x_nc = x + n * (C * D * H * W) + c * (D * H * W);

    int total_pooled = Dp * Hp * Wp;

    float thread_sum = 0.0f;

    for (int pool_idx = tid; pool_idx < total_pooled; pool_idx += block_size) {
        int dp = pool_idx / (Hp * Wp);
        int hp = (pool_idx / Wp) % Hp;
        int wp = pool_idx % Wp;

        int d_start = dp * pool_k;
        int h_start = hp * pool_k;
        int w_start = wp * pool_k;

        float max_val = -FLT_MAX;

        for (int kd = 0; kd < pool_k; kd++) {
            int d = d_start + kd;
            if (d >= D) continue;
            for (int kh = 0; kh < pool_k; kh++) {
                int h = h_start + kh;
                if (h >= H) continue;
                for (int kw = 0; kw < pool_k; kw++) {
                    int w = w_start + kw;
                    if (w >= W) continue;

                    float val = x_nc[d * (H * W) + h * W + w];
                    max_val = fmaxf(max_val, val);
                }
            }
        }

        thread_sum += max_val;
    }

    __shared__ float shared_sum[256];
    shared_sum[tid] = thread_sum;
    __syncthreads();

    for (int s = block_size / 2; s > 0; s >>= 1) {
        if (tid < s && tid + s < block_size) {
            shared_sum[tid] += shared_sum[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        float mean = shared_sum[0] / total_pooled;
        float clamped = fminf(fmaxf(mean, clamp_min), clamp_max);
        out[n * C + c] = clamped;
    }
}

torch::Tensor fused_maxpool_globalavgpool_clamp_cuda(torch::Tensor x, double clamp_min, double clamp_max, int64_t pool_k) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(x.dim() == 5, "x must be 5D (NCDHW)");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");

    int64_t N = x.size(0);
    int64_t C = x.size(1);
    int64_t D = x.size(2);
    int64_t H = x.size(3);
    int64_t W = x.size(4);

    int64_t Dp = (D - pool_k) / pool_k + 1;
    int64_t Hp = (H - pool_k) / pool_k + 1;
    int64_t Wp = (W - pool_k) / pool_k + 1;

    auto out = torch::empty({N, C, 1, 1, 1}, x.options());

    int threads = 256;
    int blocks = N * C;

    fused_maxpool_globalavgpool_clamp_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, D, H, W,
        pool_k,
        Dp, Hp, Wp,
        static_cast<float>(clamp_min),
        static_cast<float>(clamp_max)
    );

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Model that performs a transposed 3D convolution, multiplies by a scalar, applies max pooling, 
        global average pooling, and clamps the output.
        """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, scale, maxpool_kernel_size):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding)
        self.scale = scale
        self.maxpool = nn.MaxPool3d(kernel_size=maxpool_kernel_size)
        self.global_avg_pool = nn.AdaptiveAvgPool3d((1, 1, 1))
        self.clamp_min = 0
        self.clamp_max = 1
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        x = self.conv_transpose(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        x = x * self.scale
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        x = _stark_get_extension().fused_maxpool_globalavgpool_clamp_cuda(
            x.contiguous(),
            float(self.clamp_min),
            float(self.clamp_max),
            int(self.maxpool.kernel_size if isinstance(self.maxpool.kernel_size, int) else self.maxpool.kernel_size[0])
        )
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        # fused in forward_stmt_3
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        # fused in forward_stmt_3
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_6>>>
        return x
        # <<<END_IMPROVE>>>

