    int nc = blockIdx.x;
    int n = nc / C;
    int c = nc % C;

    if (n >= N || c >= C) return;

    int tid = threadIdx.x;
    int block_size = blockDim.x;

    const float* x_nc = x + n * (C * D * H * W) + c * (D * H * W);

    int total_pooled = (int)(Dp * Hp * Wp);

    float thread_sum = 0.0f;

    for (int pool_idx = tid; pool_idx < total_pooled; pool_idx += block_size) {
        int dp = pool_idx / (int)(Hp * Wp);
        int hp = (pool_idx / (int)Wp) % (int)Hp;
        int wp = pool_idx % (int)Wp;

        int d_start = dp * (int)pool_k;
        int h_start = hp * (int)pool_k;
        int w_start = wp * (int)pool_k;

        float max_val = -FLT_MAX;

        for (int kd = 0; kd < (int)pool_k; kd++) {
            int d = d_start + kd;
            if (d >= (int)D) continue;
            for (int kh = 0; kh < (int)pool_k; kh++) {
                int h = h_start + kh;
                if (h >= (int)H) continue;
                for (int kw = 0; kw < (int)pool_k; kw++) {
                    int w = w_start + kw;
                    if (w >= (int)W) continue;
                    float val = __ldg(&x_nc[d * (int)(H * W) + h * (int)W + w]) * scale;
                    max_val = fmaxf(max_val, val);
